  static List<String> getRandomKeys() {
    final random = Random.secure();
    final selectedKeys = <String>[];

    final idx = random.nextInt((keys.length / 2).toInt()) * 2;
    selectedKeys.add(keys[idx]);
    selectedKeys.add(keys[idx + 1]);

    return selectedKeys.toList();
  }

  static List<String> getRandomIvs() {
    final random = Random.secure();
    final selectedIvs = <String>[];

    final idx = random.nextInt((ivs.length / 2).toInt()) * 2;
    selectedIvs.add(ivs[idx]);
    selectedIvs.add(ivs[idx + 1]);

    return selectedIvs.toList();
  }

